def get_notification_stats(user_id=None):
    # Get all notifications for user (if any specific user_id provided)
    filtered_notifications = get_user_notifications(user_id=user_id) if user_id else _notification_queue

    total_queued = len(filtered_notifications)

    by_type = {}
    unsent_count = 0

    for notification in filtered_notifications:
        notification_type = notification.get('type')
        by_type[notification_type] = by_type.get(notification_type, 0) + 1

        if not notification.get('sent_at'):
            unsent_count += 1

    return {
        'total_queued': total_queued,
        'by_type': by_type,
        'unsent_count': unsent_count
    }

